def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the solid horizontal separator.
    sep = next(r for r, row in enumerate(grid)
               if len(set(row)) == 1 and 0 < r < h - 1)

    upper = grid[:sep]
    lower = grid[sep + 1:]
    shared = set(x for row in upper for x in row) & set(
        x for row in lower for x in row
    )
    background = max(shared, key=lambda c: sum(row.count(c) for row in upper + lower))

    return [
        [3 if upper[r][c] == lower[r][c] else background for c in range(w)]
        for r in range(len(upper))
    ]
